css:
.authlead-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2620;
    background: linear-gradient(160deg, #fbf6ef 0%, #f4ece1 60%, #efe4d4 100%);
    border-radius: 18px;
}

.authlead-container * {
    box-sizing: border-box;
}

.authlead-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #3a2417 0%, #7a3e1d 55%, #b5651d 100%);
    color: #fdf3e7;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #5a3318;
    box-shadow: 0 12px 32px rgba(58, 36, 23, 0.35);
}

.authlead-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fff6ea;
}

.authlead-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffd9a8;
    background: rgba(255, 217, 168, 0.14);
    border: 1px solid rgba(255, 217, 168, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.authlead-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f0ddc7;
}

.authlead-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6e5a47;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.authlead-period-counter #currentDay,
.authlead-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5651d;
}

.authlead-round-name {
    background: rgba(181, 101, 29, 0.14);
    color: #8a4a16;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.authlead-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a3331f;
    background: rgba(163, 51, 31, 0.10);
    border: 1px solid rgba(163, 51, 31, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.authlead-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.authlead-status-card {
    background: #fffdf9;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7d9c5;
    box-shadow: 0 6px 16px rgba(122, 62, 29, 0.10);
    border-top: 4px solid #c9b59b;
}

.authlead-card-trust { border-top-color: #2f8f6b; }
.authlead-card-engage { border-top-color: #3b82c4; }
.authlead-card-perf { border-top-color: #b5651d; }
.authlead-card-retain { border-top-color: #8a5cc7; }

.authlead-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7560;
}

.authlead-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3a2417;
    font-variant-numeric: tabular-nums;
}

.authlead-card-trust .authlead-value { color: #2f8f6b; }
.authlead-card-engage .authlead-value { color: #3b82c4; }
.authlead-card-perf .authlead-value { color: #b5651d; }
.authlead-card-retain .authlead-value { color: #8a5cc7; }

.authlead-sublabel {
    font-size: 0.76rem;
    color: #9c876f;
    line-height: 1.35;
}

.authlead-kpi-low .authlead-value { color: #c0392b; }
.authlead-kpi-low { border-top-color: #c0392b; }
.authlead-kpi-high .authlead-value { color: #2f8f6b; }
.authlead-kpi-high { border-top-color: #2f8f6b; }

.authlead-integrity-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fff7ec;
    border: 1px solid #e7d9c5;
    border-left: 5px solid #b5651d;
    color: #5a4736;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.authlead-integrity-bar #integrityDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    color: #b5651d;
}

.authlead-integrity-broken {
    border-left-color: #c0392b;
}

.authlead-integrity-broken #integrityDisplay {
    color: #c0392b;
}

.authlead-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf9;
    border-left: 5px solid #2f8f6b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(122, 62, 29, 0.08);
    border-top: 1px solid #ecdfcd;
    border-right: 1px solid #ecdfcd;
    border-bottom: 1px solid #ecdfcd;
}

.authlead-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.authlead-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #3a2417;
    margin-bottom: 6px;
}

.authlead-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #5a4736;
}

.authlead-briefing-text strong { color: #2f8f6b; }
.authlead-briefing-text em { color: #a3331f; font-style: italic; }

.authlead-controls {
    background: #fffdf9;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ecdfcd;
    box-shadow: 0 6px 16px rgba(122, 62, 29, 0.08);
}

.authlead-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #3a2417;
    border-bottom: 2px solid #ecdfcd;
    padding-bottom: 8px;
}

.authlead-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3b2c;
    margin: 16px 0 6px;
}

.authlead-container select,
.authlead-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c6ae;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffefb;
    color: #3a2417;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.authlead-container select:focus,
.authlead-container input[type="number"]:focus {
    outline: none;
    border-color: #b5651d;
    box-shadow: 0 0 0 3px rgba(181, 101, 29, 0.18);
}

.authlead-container select option {
    background-color: #fffefb;
    color: #3a2417;
}

.authlead-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5651d;
}

.authlead-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6e5a47;
    margin-top: 4px;
}

.authlead-range-readout span:last-child {
    color: #b5651d;
    font-weight: 800;
}

.authlead-hint {
    font-size: 0.8rem;
    color: #9c876f;
    margin-top: 5px;
    line-height: 1.45;
    background: #faf2e6;
    border-radius: 8px;
    padding: 8px 11px;
    border-left: 3px solid #d8c6ae;
}

.authlead-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.authlead-container .btn-primary {
    background: linear-gradient(135deg, #8a4a16 0%, #b5651d 100%);
    border: none;
    color: #fff6ea;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(138, 74, 22, 0.35);
}

.authlead-container .btn-primary:hover {
    filter: brightness(1.07);
}

.authlead-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d8c6ae;
    color: #8a7560;
    background: transparent;
}

.authlead-coach {
    background: linear-gradient(160deg, #2e3b34 0%, #243029 100%);
    color: #e4ece7;
    border: 1px solid #1d2620;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(36, 48, 41, 0.30);
}

.authlead-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6fcf9f;
    margin-bottom: 8px;
}

.authlead-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.authlead-coach-body strong { color: #6fcf9f; }
.authlead-coach-body em { color: #ffc46b; font-style: italic; }

.authlead-history,
.authlead-chart {
    background: #fffdf9;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ecdfcd;
    box-shadow: 0 6px 16px rgba(122, 62, 29, 0.08);
}

.authlead-history h3,
.authlead-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #3a2417;
}

.authlead-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #5a4736;
}

.authlead-container table#usfHistoryTable th {
    background: #f6ead9;
    color: #8a4a16;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d0b8;
}

.authlead-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe2d0;
    color: #5a4736;
}

.authlead-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fcf6ec;
}

.authlead-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .authlead-container {
        padding: 14px;
    }
    .authlead-header h1 {
        font-size: 1.7rem;
    }
    .authlead-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .authlead-value {
        font-size: 2rem;
    }
    .authlead-clock {
        margin-left: 0;
    }
    .authlead-period-counter {
        font-size: 0.88rem;
    }
    .authlead-integrity-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .authlead-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, authlead) ---- */
.authlead-completion { padding: 8px 4px 4px; }
.authlead-cm-head { text-align: center; margin-bottom: 16px; }
.authlead-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f8f6b; }
.authlead-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5aa88a; }
.authlead-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #3a2417; }
.authlead-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.authlead-cm-yes { background: rgba(47,143,107,0.14); color: #1f7a52; border: 1px solid rgba(47,143,107,0.5); }
.authlead-cm-no { background: rgba(181,101,29,0.12); color: #a5551a; border: 1px solid rgba(181,101,29,0.45); }
.authlead-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.authlead-cm-metric { flex: 1 1 92px; min-width: 84px; background: rgba(58,36,23,0.06); border: 1px solid rgba(58,36,23,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.authlead-cm-mv { display: block; font-size: 1.35rem; font-weight: 800; color: #3a2417; }
.authlead-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #7a6552; text-transform: uppercase; letter-spacing: 0.03em; }
.authlead-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #3a2417; }
.authlead-cm-insights { margin: 0; padding-left: 20px; }
.authlead-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #4a3728; }

