(function() {
    'use strict';

    class AuthLeadAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Authentic Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Sahel Digital Services Ltd. / Payments Platform Squad).
            this.START_TRUST = 2.4;       // pulse-survey trust 2.4 / 5 (bottom-quartile)
            this.START_ENGAGE = 2.7;      // engagement 2.7 / 5 (bottom-quartile)
            this.START_PERF = 55;         // delivery capacity vs client demand (0–100)
            this.START_RETAIN = 35;       // 90-day prob. both flight-risk seniors stay (%)
            this.START_INTEGRITY = 50;    // behavioural integrity (stated vs enacted values)
            this.RETENTION_BONUS = 8;     // NGN 8M reactive counter-offer (illustrative)
            this.CLIENT_ARR = 1.6;        // NGN 1.6B largest-client ARR (17% of revenue)
            this.CAPACITY_LOSS = 30;      // ~30% capacity drop if a senior leaves
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.START_TRUST,
                    engage: this.START_ENGAGE,
                    perf: this.START_PERF,
                    retain: this.START_RETAIN,
                    integrity: this.START_INTEGRITY,
                    cocreatedNorm: false,    // a "surface mistakes without blame" norm was co-created in R2
                    normViolated: false,     // a later round contradicted that norm (behavioural inconsistency)
                    coverUp: false,          // buried the dishonesty (Common Error 4)
                    bonusOnly: false,        // solved flight risk purely with counter-offers (Common Error 3)
                    bonusSpend: 0,           // NGN M spent on reactive retention
                    trustHistory: [this.START_TRUST],
                    engageHistory: [this.START_ENGAGE],
                    perfHistory: [this.START_PERF],
                    retainHistory: [this.START_RETAIN],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately a MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    cause: `people`,
                    relationship: `client`,
                    promise: `nothing`,
                    selfaware: 50,
                    open: `plan`,
                    disclose: 50,
                    norms: `impose`,
                    commit: `big`,
                    action: `bonus`,
                    seniors: `counter`,
                    sequence: `afterclient`,
                    signal: 50,
                    confront: `bury`,
                    client: `hide`,
                    consistency: `exception`,
                    kpi: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ca = document.getElementById(`causeInput`);
                const re = document.getElementById(`relationshipInput`);
                const pr = document.getElementById(`promiseInput`);
                const sa = document.getElementById(`selfawareInput`);
                if (ca) decisions.cause = ca.value;
                if (re) decisions.relationship = re.value;
                if (pr) decisions.promise = pr.value;
                if (sa) decisions.selfaware = parseInt(sa.value, 10);
                if (!Number.isFinite(decisions.selfaware) || decisions.selfaware < 0 || decisions.selfaware > 100) {
                    warn(`warn_selfaware_range`); return false;
                }
            } else if (round === 2) {
                const op = document.getElementById(`openInput`);
                const di = document.getElementById(`discloseInput`);
                const no = document.getElementById(`normsInput`);
                const co = document.getElementById(`commitInput`);
                if (op) decisions.open = op.value;
                if (di) decisions.disclose = parseInt(di.value, 10);
                if (no) decisions.norms = no.value;
                if (co) decisions.commit = co.value;
                if (!Number.isFinite(decisions.disclose) || decisions.disclose < 0 || decisions.disclose > 100) {
                    warn(`warn_disclose_range`); return false;
                }
            } else if (round === 3) {
                const ac = document.getElementById(`actionInput`);
                const se = document.getElementById(`seniorsInput`);
                const sq = document.getElementById(`sequenceInput`);
                const si = document.getElementById(`signalInput`);
                if (ac) decisions.action = ac.value;
                if (se) decisions.seniors = se.value;
                if (sq) decisions.sequence = sq.value;
                if (si) decisions.signal = parseInt(si.value, 10);
                if (!Number.isFinite(decisions.signal) || decisions.signal < 0 || decisions.signal > 100) {
                    warn(`warn_signal_range`); return false;
                }
            } else if (round === 4) {
                const cf = document.getElementById(`confrontInput`);
                const cl = document.getElementById(`clientInput`);
                const cs = document.getElementById(`consistencyInput`);
                const kp = document.getElementById(`kpiInput`);
                if (cf) decisions.confront = cf.value;
                if (cl) decisions.client = cl.value;
                if (cs) decisions.consistency = cs.value;
                if (kp) decisions.kpi = parseInt(kp.value, 10);
                if (!Number.isFinite(decisions.kpi) || decisions.kpi < 0 || decisions.kpi > 100) {
                    warn(`warn_kpi_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: trust & engage on a /5 scale; perf & retain on a /100 scale; integrity /100.
            let trustDelta = 0, engageDelta = 0, perfDelta = 0, retainDelta = 0, integrityDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Self-awareness: diagnose the trust collapse and your own stance.
                switch (d.cause) {
                    case `leadership`: trustDelta += 0.4; engageDelta += 0.2; integrityDelta += 6; coachKey = `coach_r1_leadership`; break;
                    case `people`: trustDelta -= 0.3; engageDelta -= 0.2; integrityDelta -= 4; coachKey = `coach_r1_people`; break;
                    case `me`: trustDelta -= 0.1; integrityDelta -= 2; coachKey = `coach_r1_me`; break;
                    case `process`: perfDelta += 3; trustDelta -= 0.1; coachKey = `coach_r1_process`; break;
                }

                // The pivotal relationships — knowledge-holders + the truth-teller.
                switch (d.relationship) {
                    case `seniors`: trustDelta += 0.3; retainDelta += 6; if (d.cause === `leadership`) coachKey = `coach_r1_sharp`; break;
                    case `client`: retainDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_client` : coachKey; break;
                    case `hr`: trustDelta -= 0.2; integrityDelta -= 3; break;
                    case `boss`: trustDelta -= 0.2; engageDelta -= 0.1; break;
                }

                // What NOT to promise — small kept promises rebuild trust, not declarations.
                switch (d.promise) {
                    case `honest`: trustDelta += 0.3; integrityDelta += 8; break;
                    case `nothing`: trustDelta += 0.1; integrityDelta -= 6; coachKey = `coach_r1_overpromise`; break;
                    case `overpromise`: trustDelta += 0.05; integrityDelta -= 8; retainDelta -= 2; coachKey = `coach_r1_overpromise`; break;
                    case `vague`: trustDelta -= 0.1; engageDelta -= 0.1; break;
                }

                if (d.selfaware >= 60) { trustDelta += 0.2; integrityDelta += 4; }
                else if (d.selfaware <= 25) { trustDelta -= 0.15; integrityDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r1_lowself` : coachKey; }

                summaryKey = (d.cause === `leadership` && d.relationship === `seniors` && d.promise === `honest`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Relational transparency: the first listening session.
                switch (d.open) {
                    case `acknowledge`: trustDelta += 0.5; engageDelta += 0.4; integrityDelta += 6; coachKey = `coach_r2_acknowledge`; break;
                    case `plan`: trustDelta -= 0.4; engageDelta -= 0.2; integrityDelta -= 4; perfDelta += 2; coachKey = `coach_r2_plan`; break;
                    case `forward`: trustDelta += 0.05; engageDelta += 0.1; coachKey = `coach_r2_forward`; break;
                }

                // Calibrated disclosure — a curve that peaks in the middle band, not at the extremes.
                // Too little reads as evasive; too much dumps anxiety and the seniors quit tonight.
                if (d.disclose >= 45 && d.disclose <= 70) {
                    trustDelta += 0.4; engageDelta += 0.2; retainDelta += 4; integrityDelta += 4;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_calibrated`;
                } else if (d.disclose > 70) {
                    trustDelta += 0.1; engageDelta -= 0.3; retainDelta -= 10; coachKey = `coach_r2_overdisclose`;
                } else {
                    trustDelta -= 0.2; engageDelta -= 0.1; coachKey = (coachKey === `coach_default`) ? `coach_r2_underdisclose` : coachKey;
                }

                // Co-created norms vs imposed/none. Sets the "surface mistakes without blame" norm tested in R4.
                switch (d.norms) {
                    case `cocreate`: ds.cocreatedNorm = true; trustDelta += 0.5; engageDelta += 0.4; integrityDelta += 8; if (d.open === `acknowledge`) coachKey = `coach_r2_strong`; break;
                    case `impose`: trustDelta -= 0.2; engageDelta -= 0.1; integrityDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_impose` : coachKey; break;
                    case `none`: trustDelta -= 0.1; coachKey = (coachKey === `coach_default`) ? `coach_r2_nonorms` : coachKey; break;
                }

                // One immediate, visible, keepable commitment.
                switch (d.commit) {
                    case `small`: trustDelta += 0.35; engageDelta += 0.2; integrityDelta += 6; break;
                    case `big`: trustDelta += 0.1; integrityDelta -= 8; retainDelta -= 2; coachKey = `coach_r2_bigcommit`; break;
                    case `none`: trustDelta -= 0.1; engageDelta -= 0.1; break;
                }

                summaryKey = (d.open === `acknowledge` && d.norms === `cocreate` && d.disclose >= 45 && d.disclose <= 70 && d.commit === `small`) ? `sum_r2_good` :
                             (d.disclose > 70 ? `sum_r2_overdisclose` : `sum_r2_weak`);
            } else if (round === 3) {
                // Balanced processing: the development/retention action under pressure.
                switch (d.action) {
                    case `stay`: trustDelta += 0.4; engageDelta += 0.5; retainDelta += 14; integrityDelta += 6; coachKey = `coach_r3_stay`; break;
                    case `promote`: trustDelta += 0.3; engageDelta += 0.4; retainDelta += 6; coachKey = `coach_r3_promote`; break;
                    case `skills`: engageDelta += 0.3; perfDelta += 6; retainDelta += 4; coachKey = `coach_r3_skills`; break;
                    case `redistribute`: perfDelta += 8; retainDelta -= 4; trustDelta -= 0.1; coachKey = `coach_r3_redistribute`; break;
                    case `bonus`:
                        // Fast and certain, but signals only exit threats get rewarded (Common Error 3).
                        ds.bonusSpend += this.RETENTION_BONUS * 2;
                        retainDelta += 16; trustDelta -= 0.5; engageDelta -= 0.4; integrityDelta -= 8;
                        ds.bonusOnly = true; coachKey = `coach_r3_bonus`;
                        break;
                }

                // Treating the seniors without rewarding only the loudest exit threat.
                switch (d.seniors) {
                    case `proactive`: trustDelta += 0.3; engageDelta += 0.3; retainDelta += 8; integrityDelta += 6; if (d.action === `stay`) coachKey = `coach_r3_sharp`; break;
                    case `counter`:
                        ds.bonusSpend += this.RETENTION_BONUS;
                        retainDelta += 8; trustDelta -= 0.4; engageDelta -= 0.3; integrityDelta -= 6;
                        ds.bonusOnly = true; coachKey = `coach_r3_counter`;
                        break;
                    case `ignore`: retainDelta -= 8; trustDelta -= 0.1; coachKey = (coachKey === `coach_default`) ? `coach_r3_ignore` : coachKey; break;
                }

                // Sequence against the 14-day client deadline.
                switch (d.sequence) {
                    case `parallel`: perfDelta += 6; trustDelta += 0.2; integrityDelta += 4; break;
                    case `afterclient`: trustDelta -= 0.2; engageDelta -= 0.2; perfDelta += 2; break;
                    case `ignoreclient`: perfDelta -= 8; retainDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_ignoreclient` : coachKey; break;
                }

                if (d.signal >= 60) { trustDelta += 0.2; engageDelta += 0.1; }
                else if (d.signal <= 25) { trustDelta -= 0.1; }

                summaryKey = (d.seniors === `proactive` && (d.action === `stay` || d.action === `promote` || d.action === `skills`) && d.sequence === `parallel`) ? `sum_r3_good` :
                             (ds.bonusOnly ? `sum_r3_bonus` : `sum_r3_weak`);
            } else if (round === 4) {
                // Internalized moral perspective: resolve the values conflict under cost.
                switch (d.confront) {
                    case `restore`: trustDelta += 0.6; engageDelta += 0.5; integrityDelta += 12; retainDelta += 6; coachKey = `coach_r4_restore`; break;
                    case `bury`:
                        ds.coverUp = true;
                        trustDelta -= 0.3; integrityDelta -= 14; retainDelta += 4; perfDelta -= 8; coachKey = `coach_r4_bury`;
                        break;
                    case `punish`:
                        trustDelta -= 0.5; engageDelta -= 0.5; retainDelta -= 14; integrityDelta -= 6; coachKey = `coach_r4_punish`;
                        // Public dressing-down also violates a co-created "surface mistakes without blame" norm.
                        if (ds.cocreatedNorm) { ds.normViolated = true; integrityDelta -= 10; trustDelta -= 0.3; }
                        break;
                    case `delegate`: trustDelta -= 0.3; engageDelta -= 0.2; integrityDelta -= 8; coachKey = `coach_r4_delegate`; break;
                }

                // Protect the team's integrity with the client.
                switch (d.client) {
                    case `honest`: perfDelta += 8; integrityDelta += 8; trustDelta += 0.2; coachKey = (d.confront === `restore`) ? `coach_r4_facedown` : coachKey; break;
                    case `hide`: perfDelta -= 10; integrityDelta -= 8; ds.coverUp = true; coachKey = (coachKey === `coach_default`) ? `coach_r4_hide` : coachKey; break;
                    case `blame`: trustDelta -= 0.4; engageDelta -= 0.4; retainDelta -= 10; integrityDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_blame` : coachKey; break;
                }

                // Reconcile keeping a high-value engineer with not normalising dishonesty.
                switch (d.consistency) {
                    case `apply`: trustDelta += 0.4; engageDelta += 0.3; integrityDelta += 10; break;
                    case `exception`:
                        // Bending the norm for the valuable person = behavioural inconsistency.
                        if (ds.cocreatedNorm) ds.normViolated = true;
                        trustDelta -= 0.4; engageDelta -= 0.3; integrityDelta -= 12; coachKey = (coachKey === `coach_default`) ? `coach_r4_exception` : coachKey;
                        break;
                    case `expel`: perfDelta -= this.CAPACITY_LOSS * 0.5; retainDelta -= 12; integrityDelta += 4; trustDelta += 0.1; coachKey = (coachKey === `coach_default`) ? `coach_r4_expel` : coachKey; break;
                }

                if (d.kpi >= 60) { trustDelta += 0.2; perfDelta += 4; integrityDelta += 4; }
                else if (d.kpi <= 25) { trustDelta -= 0.1; perfDelta -= 3; }

                summaryKey = (d.confront === `restore` && d.client === `honest` && d.consistency === `apply`) ? `sum_r4_good` :
                             (ds.coverUp ? `sum_r4_coverup` : `sum_r4_weak`);
            }

            // A norm broken after being co-created does more damage than a norm never set.
            if (ds.normViolated && coachKey !== `coach_r4_punish` && coachKey !== `coach_r4_exception`) {
                coachKey = `coach_normbroken`;
            }

            // Apply deltas with clamps. Trust & engage 0–5; perf & retain & integrity 0–100.
            ds.trust = Math.max(0, Math.min(5, Math.round((ds.trust + trustDelta) * 100) / 100));
            ds.engage = Math.max(0, Math.min(5, Math.round((ds.engage + engageDelta) * 100) / 100));
            ds.perf = Math.max(0, Math.min(100, Math.round(ds.perf + perfDelta)));
            ds.retain = Math.max(0, Math.min(100, Math.round(ds.retain + retainDelta)));
            ds.integrity = Math.max(0, Math.min(100, Math.round(ds.integrity + integrityDelta)));

            ds.trustHistory.push(ds.trust);
            ds.engageHistory.push(ds.engage);
            ds.perfHistory.push(ds.perf);
            ds.retainHistory.push(ds.retain);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta * 100) / 100,
                engage: ds.engage,
                engageDelta: Math.round(engageDelta * 100) / 100,
                perf: ds.perf,
                perfDelta: Math.round(perfDelta),
                retain: ds.retain,
                retainDelta: Math.round(retainDelta),
                integrity: ds.integrity,
                integrityDelta: Math.round(integrityDelta),
                bonusOnly: ds.bonusOnly,
                coverUp: ds.coverUp,
                normViolated: ds.normViolated,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtScore5(v) {
            // /5 scale, one decimal. Spanish uses a comma decimal separator.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es`) ? s.replace(`.`, `,`) : s;
        }

        _fmtNaira(v) {
            // NGN millions, naira symbol. English "₦8M"; Spanish "8 M₦".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const abs = Math.abs(Number(v));
            if (lang === `es`) return `${abs.toFixed(0)} M₦`;
            return `₦${abs.toFixed(0)}M`;
        }

