        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                authleadChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.engageHistory },
                        { data: ds.perfHistory },
                        { data: ds.retainHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const trust = ds.trust;
            const engage = ds.engage;
            const perf = Math.round(ds.perf);
            const retain = Math.round(ds.retain);
            const integrity = Math.round(ds.integrity);
            const composite = Math.round(
                (trust / 5) * 100 * 0.26 +
                (engage / 5) * 100 * 0.18 +
                perf * 0.16 +
                retain * 0.18 +
                integrity * 0.22
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="authlead-cm-badge authlead-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="authlead-cm-badge authlead-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.coverUp) failBadge += ` <span class="authlead-cm-badge authlead-cm-no">` + T(`cm_coverup`) + `</span>`;
            if (s.bonusOnly) failBadge += ` <span class="authlead-cm-badge authlead-cm-no">` + T(`cm_bonus`) + `</span>`;
            if (s.normViolated) failBadge += ` <span class="authlead-cm-badge authlead-cm-no">` + T(`cm_normbroken`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const fmt5 = (typeof this._fmtScore5 === `function`) ? this._fmtScore5.bind(this) : function(v){ return v; };
            const metrics = ``
                + `<div class="authlead-cm-metric"><span class="authlead-cm-mv">` + fmt5(s.trust || 0) + `</span><span class="authlead-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="authlead-cm-metric"><span class="authlead-cm-mv">` + fmt5(s.engage || 0) + `</span><span class="authlead-cm-ml">` + T(`cm_m_engage`) + `</span></div>`
                + `<div class="authlead-cm-metric"><span class="authlead-cm-mv">` + Math.round(s.perf || 0) + `</span><span class="authlead-cm-ml">` + T(`cm_m_perf`) + `</span></div>`
                + `<div class="authlead-cm-metric"><span class="authlead-cm-mv">` + Math.round(s.retain || 0) + `%</span><span class="authlead-cm-ml">` + T(`cm_m_retain`) + `</span></div>`
                + `<div class="authlead-cm-metric"><span class="authlead-cm-mv">` + Math.round(s.integrity || 0) + `</span><span class="authlead-cm-ml">` + T(`cm_m_integrity`) + `</span></div>`;
            return ``
                + `<div class="authlead-completion">`
                +   `<div class="authlead-cm-head">`
                +     `<div class="authlead-cm-score">` + score + `<span class="authlead-cm-score-max">/100</span></div>`
                +     `<div class="authlead-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="authlead-cm-metrics">` + metrics + `</div>`
                +   `<div class="authlead-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="authlead-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = ds.trust;
            const engage = ds.engage;
            const perf = Math.round(ds.perf);
            const retain = Math.round(ds.retain);
            const integrity = Math.round(ds.integrity);

            const composite = this._composite(ds);

            const trusted = trust >= 3.8 && engage >= 3.6;
            const retained = retain >= 70;
            const consistent = integrity >= 65 && !ds.normViolated;
            const exposed = ds.coverUp || ds.bonusOnly || ds.normViolated || integrity < 40;

            let performanceKey = `grade_fractured`;
            if (trusted && retained && consistent && composite >= 75) performanceKey = `grade_turnaround`;
            else if (consistent && retained) performanceKey = `grade_rebuilt`;
            else if (ds.coverUp) performanceKey = `grade_coverup`;
            else if (ds.bonusOnly) performanceKey = `grade_bonustrap`;
            else if (ds.normViolated) performanceKey = `grade_normbroken`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (trusted && retained && consistent) insights.push(window.mySimulation.t(`insight_authentic`));
            else if (ds.coverUp) insights.push(window.mySimulation.t(`insight_coverup`));
            else if (ds.bonusOnly) insights.push(window.mySimulation.t(`insight_bonus`));
            else if (ds.normViolated) insights.push(window.mySimulation.t(`insight_normbroken`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (trust < 3.0) insights.push(window.mySimulation.t(`insight_lowtrust`));
            if (retain < 50) insights.push(window.mySimulation.t(`insight_lowretain`));
            if (integrity >= 70 && !ds.normViolated) insights.push(window.mySimulation.t(`insight_integrity`));
            if (perf < 45) insights.push(window.mySimulation.t(`insight_lowperf`));

            return {
                trust: trust,
                engage: engage,
                perf: perf,
                retain: retain,
                integrity: integrity,
                trusted: trusted,
                retained: retained,
                consistent: consistent,
                exposed: exposed,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (trusted && retained && consistent && composite >= 75),
                coverUp: ds.coverUp,
                bonusOnly: ds.bonusOnly,
                normViolated: ds.normViolated,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.coverUp) return window.mySimulation.t(`hint_coverup`);
            if (ds.normViolated) return window.mySimulation.t(`hint_normbroken`);
            if (ds.bonusOnly) return window.mySimulation.t(`hint_bonus`);
            if (ds.trust < 2.4 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_lowtrust`);
            if (ds.retain < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_lowretain`);
            if (ds.trust >= 3.6 && ds.retain >= 65 && ds.integrity >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

